create table if not exists service_budgets(agent_id uuid not null references agents(id) on delete cascade,service varchar(40) not null,per_request numeric(78,0) not null,daily_budget numeric(78,0) not null,monthly_budget numeric(78,0) not null,enabled boolean not null default true,primary key(agent_id,service));
create table if not exists service_quotes(id uuid primary key,service varchar(40) not null,agent_id uuid,requesT_hash char(64) not null,amount numeric(78,0) not null,asset varchar(220) not null,network varchar(80) not null,provider_id varchar(160),expires_at timestamptz not null,status varchar(20) not null check(status in('offered','authorized','consumed','expired','failed')),payment_id varchar(128),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists service_quote_payment_unique on service_quotes(payment_id) where payment_id is not null;
create index if not exists service_quotes_expiry_idx on service_quotes(status,expires_at);
create table if not exists service_usage(id uuid primary key,service varchar(40) not null,agent_id uuid,quote_id uuid not null references service_quotes(id),request_id varchar(128) not null unique,provider_id varchar(160),input_units bigint not null default 0,output_units bigint not null default 0,billed_amount numeric(78,0) not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists service_usage_budget_idx on service_usage(agent_id,service,created_at);
insert into schema_migrations(version) values('005_service_gateway') on conflict do nothing;
